class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> nxt;
        vector<int> st;
        for (int x : nums2) {
            while (!st.empty() && st.back() < x) {
                nxt[st.back()] = x;
                st.pop_back();
            }
            st.push_back(x);
        }
        vector<int> res;
        for (int x : nums1) {
            res.push_back(nxt.count(x) ? nxt[x] : -1);
        }
        return res;
    }
};

class Solution {
    public int[] nextGreaterElement(int[] nums1, int[] nums2) {
        Map<Integer, Integer> nxt = new HashMap<>();
        int[] st = new int[nums2.length];
        int top = 0;
        for (int x : nums2) {
            while (top > 0 && st[top - 1] < x) {
                nxt.put(st[--top], x);
            }
            st[top++] = x;
        }
        int[] res = new int[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            res[i] = nxt.getOrDefault(nums1[i], -1);
        }
        return res;
    }
}

var nextGreaterElement = function(nums1, nums2) {
    const nxt = new Map();
    const st = [];
    for (let i = 0; i < nums2.length; i++) {
        const x = nums2[i];
        while (st.length > 0 && st[st.length - 1] < x) {
            nxt.set(st.pop(), x);
        }
        st.push(x);
    }
    return nums1.map(x => nxt.has(x) ? nxt.get(x) : -1);
};
